const memSel=(n,en,ar)=>{ const s=String(ask(en+' member id(s) ('+ST().mem.map(m=>m.id).slice(-8).join(', ')+')',ar,ST().mem.slice(-n).map(m=>m.id).join(','))||'').split(/[\s,]+/).map(id=>ST().mem.find(m=>m.id===id)).filter(Boolean); return s.length===n?s:null; };
function inter(m,o){ /* closest points of two 3D lines: parameters along m and o */ const d1=[0,1,2].map(i=>m.b[i]-m.a[i]), d2=[0,1,2].map(i=>o.b[i]-o.a[i]), r=[0,1,2].map(i=>m.a[i]-o.a[i]), dot=(p,q)=>p[0]*q[0]+p[1]*q[1]+p[2]*q[2], a=dot(d1,d1), b=dot(d1,d2), c=dot(d2,d2), d=dot(d1,r), e=dot(d2,r), den=a*c-b*b; if(Math.abs(den)<1e-12)return null; const s=(b*e-c*d)/den, t=(a*e-b*d)/den, P=[0,1,2].map(i=>m.a[i]+d1[i]*s), Q=[0,1,2].map(i=>o.a[i]+d2[i]*t); return {s,t,P,gap:Math.hypot(P[0]-Q[0],P[1]-Q[1],P[2]-Q[2])}; }
