const DAY=864e5, serial=d=>Math.round((Date.UTC(d.getFullYear(),d.getMonth(),d.getDate())-Date.UTC(1899,11,30))/DAY), fromSer=n=>new Date(Date.UTC(1899,11,30)+Math.round(n)*DAY);
