 SIN:a=>Math.sin(a[0]),COS:a=>Math.cos(a[0]),TAN:a=>Math.tan(a[0]),RADIANS:a=>a[0]*Math.PI/180,DEGREES:a=>a[0]*180/Math.PI,PRODUCT:a=>N(a).reduce((s,x)=>s*x,1),SUMSQ:a=>N(a).reduce((s,x)=>s+x*x,0),SIGN:a=>Math.sign(a[0]),ROUNDUP:a=>{ const k=Math.pow(10,a[1]||0); return Math.sign(a[0])*Math.ceil(Math.abs(a[0])*k)/k; },ROUNDDOWN:a=>{ const k=Math.pow(10,a[1]||0); return Math.sign(a[0])*Math.floor(Math.abs(a[0])*k)/k; },
 VLOOKUP:a=>{ const g=a[1], col=(a[2]|0)-1, exact=a[3]===undefined?false:!a[3]; if(!g||!g.nr||col<0||col>=g.nc)throw 0; let hit=-1; for(let r=0;r<g.nr;r++){ const v=cell(g,r,0); if(v==a[0]){ hit=r; break; } if(!exact&&typeof v==='number'&&v<=a[0])hit=r; } if(hit<0)throw 0; return cell(g,hit,col); },
