const vov=(tab,panel,en,help,run)=>PXX.ov('survey',tab,panel,en,help,run);
function panorama(){ let P=[]; try{ P=svParse(); }catch(e){} const ev=[], seen={}, xy={}; P.forEach(p=>{ if(seen[p.id])ev.push(['Duplicate point number',p.id]); seen[p.id]=1; const k=p.e.toFixed(3)+','+p.n.toFixed(3); if(xy[k])ev.push(['Same coordinates as '+xy[k],p.id]); xy[k]=p.id; });
 if(P.length>3){ const z=P.map(p=>p.z).sort((a,b)=>a-b), q1=z[Math.floor(z.length*.25)], q3=z[Math.floor(z.length*.75)], iq=q3-q1; P.forEach(p=>{ if(p.z<q1-3*iq||p.z>q3+3*iq)ev.push(['Elevation outlier '+p.z,p.id]); }); }
 return {points:P,events:ev}; }
PXM.panorama=panorama;
vov('Home','Palettes','Panorama',['Panorama: the point editor vista (every survey point) and the event viewer (duplicate numbers, coincident points, elevation outliers)','بانوراما: محرر النقط (كل نقط المساحة) وعارض الأحداث (أرقام مكررة، نقط متطابقة، مناسيب شاذة)'],()=>{ const r=panorama(); rep(b2('Panorama: events','بانوراما: الأحداث'),['Event','Point'],r.events.length?r.events:[['No events','-']],r.points.length+' points, '+r.events.length+' event(s)'); return r; });
vov('Home','Palettes','Tool Palettes',['Tool Palettes: the S.X library (symbols, hatches, styles) to drag onto the drawing','لوحات الأدوات: مكتبة S.X (رموز، تهشير، أنماط) للسحب على الرسمة'],()=>XC.lb_sx.run());
const PIPE={PVC:[150,'C=150'],HDPE:[140,'C=140'],DI:[130,'C=130'],STEEL:[120,'C=120']};
function pressureNet(pts,dn,mat,cover,Q){ const C=PIPE[mat][0], segs=[], bends=[]; let L=0; for(let i=1;i<pts.length;i++){ const a=pts[i-1], b=pts[i], l=Math.hypot(b[0]-a[0],b[1]-a[1]); L+=l; segs.push({a,b,l:r3(l)}); if(i>1){ const p=pts[i-2], d1=Math.atan2(a[1]-p[1],a[0]-p[0]), d2=Math.atan2(b[1]-a[1],b[0]-a[0]); let ang=Math.abs((d2-d1)*180/Math.PI); if(ang>180)ang=360-ang; if(ang>1){ const std=[11.25,22.5,45,90].find(s=>ang<=s+1)||90; bends.push({at:a,ang:r2(ang),fit:std+'° bend'}); } } }
 const D=dn/1000, hf=Q>0?10.67*L*Math.pow(Q/1000,1.852)/(Math.pow(C,1.852)*Math.pow(D,4.87)):0, v=Q>0?(Q/1000)/(Math.PI*D*D/4):0; return {segs,bends,L:r3(L),pipes:Math.ceil(L/6),hf:r3(hf),v:r3(v),dn,mat,cover}; }
PXM.pressureNet=pressureNet;
vov('Home','Create Design','Pressure Network',['Pressure network along points: DN, material, cover, flow; pipes (6 m lengths), bends at each angle point, velocity and Hazen-Williams head loss','شبكة ضغط على نقط: القطر والخامة والغطاء والتصرف؛ المواسير والأكواع وسرعة المياه وفاقد هيزن-ويليامز'],()=>{ const s=String(ask('Pressure network: points E,N E,N ... | DN mm | material (PVC/HDPE/DI/STEEL) | cover m | flow l/s','شبكة ضغط: النقط | القطر مم | الخامة | الغطاء م | التصرف ل/ث','0,0 100,0 150,50 | 200 | DI | 1.2 | 30')||'').split('|').map(x=>x.trim()), P=(s[0]||'').split(/\s+/).map(q=>nums(q,2)).filter(Boolean), dn=+s[1], mat=(s[2]||'').toUpperCase(), cov=+s[3]||1, Q=+s[4]||0;
 if(P.length<2||!(dn>0)||!PIPE[mat])return need('Example: 0,0 100,0 150,50 | 200 | DI | 1.2 | 30','مثال: 0,0 100,0 150,50 | 200 | DI | 1.2 | 30'); const r=pressureNet(P,dn,mat,cov,Q); const sv=DATA.pnet=DATA.pnet||[]; sv.push(r); persist(); PXM.lastP=r;
 rep(b2('Pressure Network','شبكة الضغط'),['Item','Value'],[['Length',r.L+' m'],['Pipes (6 m)',r.pipes],['Bends',r.bends.map(b=>b.fit).join(', ')||'none'],['Velocity',r.v+' m/s'],['Head loss (H-W '+PIPE[mat][1]+')',r.hf+' m'],['Cover',cov+' m']],'DN'+dn+' '+mat); return r; });
vov('Insert','Map','Attach image',['Attach an image (scanned map, aerial photo) to the drawing at an insertion point and width','اربط صورة (خريطة ممسوحة، صورة جوية) بالرسمة عند نقطة إدراج وبعرض'],()=>PXX.pick('.png,.jpg,.jpeg,.gif,.webp,.svg').then(f=>PXC2.attachFile(f)));

