const cov=(tab,panel,en,help,run)=>PXX.ov('coord',tab,panel,en,help,run);
function meshes(){ const out=[]; scene.updateMatrixWorld(true); scene.traverse(o=>{ if(o.isMesh&&o.visible&&o.geometry&&o.geometry.attributes.position&&!(o.userData&&o.userData.vsEdge))out.push(o); }); return out; }
function fbx(){ const M=meshes(); let id=100000, objs='', con=''; const v=new T.Vector3();
 M.forEach((o,k)=>{ const g=o.geometry, P=g.attributes.position, I=g.index?g.index.array:Array.from({length:P.count},(x,i)=>i), vs=[]; for(let i=0;i<P.count;i++){ v.fromBufferAttribute(P,i).applyMatrix4(o.matrixWorld); vs.push(+v.x.toFixed(4),+v.y.toFixed(4),+v.z.toFixed(4)); } const pi=[]; for(let i=0;i+2<I.length;i+=3)pi.push(I[i],I[i+1],-I[i+2]-1);
  const gid=++id, mid=++id, nm=(o.name||'Mesh'+k).replace(/[^\w.-]/g,'_'); objs+='\tGeometry: '+gid+', "Geometry::'+nm+'", "Mesh" {\n\t\tVertices: *'+vs.length+' {\n\t\t\ta: '+vs.join(',')+'\n\t\t}\n\t\tPolygonVertexIndex: *'+pi.length+' {\n\t\t\ta: '+pi.join(',')+'\n\t\t}\n\t\tGeometryVersion: 124\n\t}\n\tModel: '+mid+', "Model::'+nm+'", "Mesh" {\n\t\tVersion: 232\n\t}\n'; con+='\tC: "OO",'+gid+','+mid+'\n\tC: "OO",'+mid+',0\n'; });
 return {n:M.length,text:'; FBX 7.4.0 project file\n; Created by T.O X\nFBXHeaderExtension:  {\n\tFBXHeaderVersion: 1003\n\tFBXVersion: 7400\n\tCreator: "T.O X"\n}\nGlobalSettings:  {\n\tVersion: 1000\n\tProperties70:  {\n\t\tP: "UpAxis", "int", "Integer", "",1\n\t\tP: "UnitScaleFactor", "double", "Number", "",100\n\t}\n}\nObjects:  {\n'+objs+'}\nConnections:  {\n'+con+'}\n'}; }
PXM.fbx=fbx;
cov('Output','Export Scene','FBX',['Export the visible 3D scene as FBX 7.4 ASCII (meshes in world coordinates, metres, Y up) for 3ds Max, Maya, Navisworks','صدّر المشهد الظاهر FBX 7.4 نصي (أسطح بالإحداثيات العامة، متر) لـ 3ds Max وMaya ونافيس ووركس'],()=>{ const r=fbx(); if(!r.n)return need('Nothing visible to export.','مفيش حاجة ظاهرة.'); out('XTO_scene.fbx',r.text); xSt(wd('FBX: '+r.n+' meshes','FBX: '+r.n+' سطح')); return r.n; });
function kml(){ const ll=geoLL(); if(!isFinite(ll[0])||!isFinite(ll[1]))throw new Error(b2('Set the site location first (Geo / Map).','حدد موقع المشروع الأول.')); const R=6378137, toLL=(x,z)=>[ll[0]-z/R*180/Math.PI,ll[1]+x/(R*Math.cos(ll[0]*Math.PI/180))*180/Math.PI], B=new T.Box3(); let pm='', n=0;
 meshes().forEach(o=>{ B.setFromObject(o); if(B.isEmpty())return; const h=B.max.y-B.min.y; if(!(h>=0))return; const c=[[B.min.x,B.min.z],[B.max.x,B.min.z],[B.max.x,B.max.z],[B.min.x,B.max.z],[B.min.x,B.min.z]].map(q=>{ const g=toLL(q[0],q[1]); return g[1].toFixed(7)+','+g[0].toFixed(7)+','+Math.max(0,B.max.y).toFixed(2); }).join(' ');
  pm+='<Placemark><name>'+esc(o.name||('Element '+(n+1)))+'</name><styleUrl>#m</styleUrl><Polygon><extrude>1</extrude><altitudeMode>relativeToGround</altitudeMode><outerBoundaryIs><LinearRing><coordinates>'+c+'</coordinates></LinearRing></outerBoundaryIs></Polygon></Placemark>\n'; n++; });
 return {n,text:'<?xml version="1.0" encoding="UTF-8"?>\n<kml xmlns="http://www.opengis.net/kml/2.2"><Document><name>T.O X model</name><Style id="m"><PolyStyle><color>990078ff</color></PolyStyle><LineStyle><color>ff333333</color></LineStyle></Style>\n'+pm+'</Document></kml>\n'}; }
PXM.kml=kml;
cov('Output','Export Scene','Google Earth KML',['Export the model to Google Earth KML: each element as an extruded footprint at the site location','صدّر النموذج KML لجوجل إيرث: كل عنصر كمسقط مرفوع عند موقع المشروع'],()=>{ const r=kml(); if(!r.n)return need('Nothing visible to export.','مفيش حاجة ظاهرة.'); out('XTO_model.kml',r.text); xSt(wd('KML: '+r.n+' elements','KML: '+r.n+' عنصر')); return r.n; });
